function field(string $label,string $name,array $item,string $type='text',bool $required=true): void {
    $value=$_SERVER['REQUEST_METHOD']==='POST' && post('action')==='save' ? post($name,20000) : ($item[$name]??'');
    echo '<label>'.e($label);
    if($type==='textarea') echo '<textarea name="'.e($name).'" rows="'.(in_array($name,['body','privacy'],true)?12:5).'" '.($required?'required':'').'>'.e(str_replace('\\n',"\n",(string)$value)).'</textarea>';
    else echo '<input type="'.e($type).'" name="'.e($name).'" value="'.e($value).'" '.($required?'required':'').'>';
    echo '</label>';
}
